{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "transformer",
    "window": 3,
    "threshold_q": 0.9,
    "persistence": 1
  },
  "intent_understood_as": "early_attack_detection",
  "reason": "Intent demands fastest detection with false alarms ≤1.0/h. Transformer w3 p1 at default threshold gives 0.01/h and 10.9s DNS delay. Lowering to q0.9 trades a small false-alarm increase (still well under 1.0/h) for earlier detection, satisfying the budget while minimising delay. AE was rejected because its 24.3/h at default violates the hard 1.0/h constraint."
